import sys
from collections import deque

def bfs_shortest_paths(tree, start):
    dist = [-1] * len(tree)
    dist[start] = 0
    queue = deque([start])
    while queue:
        node = queue.popleft()
        for neighbor in tree[node]:
            if dist[neighbor] == -1:
                dist[neighbor] = dist[node] + 1
                queue.append(neighbor)
    return dist

def is_bipartite(graph):
    n = len(graph)
    color = [0] * n
    for start in range(n):
        if color[start] == 0:
            queue = deque([start])
            color[start] = 1
            while queue:
                node = queue.popleft()
                for neighbor in graph[node]:
                    if color[neighbor] == 0:
                        color[neighbor] = -color[node]
                        queue.append(neighbor)
                    elif color[neighbor] == color[node]:
                        return False, []
    set_u = [i + 1 for i in range(n) if color[i] == 1]
    set_v = [i + 1 for i in range(n) if color[i == -1]
    return True, (set_u, set_v)

def solve():
    import sys
    input = sys.stdin.read().splitlines()
    index = 0
    t = int(input[index])
    index += 1
    results = []
    for _ in range(t):
        n = int(input[index])
        index += 1
        tree = [[] for _ in range(n)]
        for _ in range(n - 1):
            u, v = map(int, input[index].split())
            index += 1
            tree[u - 1].append(v - 1)
            tree[v - 1].append(u - 1)

        max_k = n // 2
        for k in range(1, max_k + 1):
            h_k = [set() for _ in range(n)]
            for i in range(n):
                distances = bfs_shortest_paths(tree, i)
                for j in range(n):
                    if distances[j] <= k:
                        h_k[i].add(j)
                        h_k[j].add(i)

            bipartite, partition = is_bipartite(h_k)
            if bipartite:
                set_u, set_v = partition
                results.append((k, set_u, set_v))
                break

    for result in results:
        k, set_u, set_v = result
        print(k)
        print(" ".join(map(str, set_u)))
        print(" ".join(map(str, set_v)))

solve()
